def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Start of a new field
        if i == len(line):
            # End of line - we have a complete field (possibly empty)
            fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: must be comma or end of line
                        if i == len(line) or line[i] == ',':
                            fields.append(''.join(field))
                            if i < len(line):
                                i += 1  # Skip the comma
                            break
                        else:
                            # Malformed: closing quote not followed by comma or end
                            return None
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field - runs to next comma or end of line
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Malformed: unquoted field contains a quote
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))

            if i < len(line):
                # Skip the comma
                i += 1

    return fields

